var DATA={"label": "Time-Series Forecasting Engine - public implementations surv", "rows": [["Jupyter", "15"], ["  Jupyter ", "38"], ["pandas", "21"], ["Cross-validation", "50"], ["  Cross-validation ", "84"], ["SHAP", "46"], ["scikit-learn", "42"], ["  scikit-learn ", "81"], ["", ""], ["Jupyter", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
